// ════════════════════════════════════════════════════════════
//  Esquema del recurso Task
// ════════════════════════════════════════════════════════════

export type TaskStatus = "pendiente" | "completada";

/**
 * Recurso Task.
 * - id: generado por el sistema al crear.
 * - title: obligatorio.
 * - description: opcional en creación, siempre presente en respuesta (string vacío si no se provee).
 * - status: por defecto "pendiente" al crear.
 * - created_at / updated_at: ISO 8601, generados por el sistema.
