export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  created_at: string;
  updated_at: string;
}

// ════════════════════════════════════════════════════════════
//  Cuerpos de solicitud
// ════════════════════════════════════════════════════════════

/** POST /tasks */
export interface CreateTaskRequest {
  title: string;
  description?: string;
}

/** PUT /tasks/{id} */
export interface UpdateTaskRequest {
  title: string;
  description: string;
}

// ════════════════════════════════════════════════════════════
//  Cuerpos de respuesta
// ════════════════════════════════════════════════════════════

export interface TaskResponse {
  data: Task;
}

export interface TaskListResponse {
  data: Task[];
}

export interface ErrorResponse {
  error: {
    code: string;
    message: string;
  };
}

// ════════════════════════════════════════════════════════════
//  Parámetros de query para GET /tasks
// ════════════════════════════════════════════════════════════

export interface ListTasksQuery {
  /** Filtrar por estado. Si se omite, devuelve todas. */
  status?: TaskStatus;
  /** Ordenar por created_at. "created_at" = ascendente, "-created_at" = descendente. Default: "created_at". */
  sort?: "created_at" | "-created_at";
}

// ════════════════════════════════════════════════════════════
//  Definición de endpoints (nivel de tipos)
// ════════════════════════════════════════════════════════════

export interface Endpoints {
  "POST /tasks": {
    request: CreateTaskRequest;
    success: 201;
    successBody: TaskResponse;
    errors: [400];
  };
  "GET /tasks": {
    request: undefined;
    query: ListTasksQuery;
    success: 200;
    successBody: TaskListResponse;
    errors: [];
  };
  "GET /tasks/{id}": {
    request: undefined;
    success: 200;
    successBody: TaskResponse;
    errors: [404];
  };
  "PUT /tasks/{id}": {
    request: UpdateTaskRequest;
    success: 200;
    successBody: TaskResponse;
    errors: [400, 404];
  };
  "DELETE /tasks/{id}": {
    request: undefined;
    success: 204;
    successBody: undefined;
    errors: [404];
  };
  "POST /tasks/{id}/complete": {
    request: undefined;
    success: 200;
    successBody: TaskResponse;
    errors: [404];
  };
}

// ════════════════════════════════════════════════════════════
