  | "POST /tasks"
  | "GET /tasks"
  | "GET /tasks/{id}"
  | "PUT /tasks/{id}"
  | "DELETE /tasks/{id}"
  | "POST /tasks/{id}/complete";
type AssertEndpoints =
  ExpectedEndpoints extends EndpointKeys
    ? EndpointKeys extends ExpectedEndpoints
      ? true
      : never
    : never;
const _endpointsOk: AssertEndpoints = true;

// Verificar que TaskStatus solo permite los dos valores esperados
type AssertStatus = "pendiente" | "completada" extends TaskStatus
